  const blocks=previewBlocks(e);
  const blockCard=b=><div key={b.id||b.label+b.code} className="command-example"><div className="command-code-heading"><strong>{b.label} · {b.where}</strong><button type="button" onClick={()=>copy(b.code)} aria-label={'Copy '+e.title+' '+b.label}>Copy</button></div>{b.requires&&<p><strong>Requires:</strong> {b.requires}</p>}<pre><code>{b.code}</code></pre>{b.note&&<p>{b.note}</p>}{b.failures?.length>0&&<details><summary>If this operation fails</summary><dl>{b.failures.map(f=><div key={f.symptom}><dt>{f.symptom}</dt><dd>{f.action}</dd></div>)}</dl></details>}{b.next&&<p><strong>Next:</strong> {b.next}</p>}{b.href&&<p><a href={b.href}>{b.sourceId?'Read the full original section':'Read the operation guidance'}</a></p>}</div>;
